import{_ as e,o as d,c as r,a2 as o}from"./chunks/framework.z3u3TMv0.js";const a="/ultra_guides/shots/27-error-detail-modal.png",g=JSON.parse('{"title":"错误代码排错","description":"","frontmatter":{"head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"错误代码排错 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern Ultra user guides — AI roleplay, character cards, BYOK and local models."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/manual/errors"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/manual/errors"}]]},"headers":[],"relativePath":"manual/errors.md","filePath":"manual/errors.md","lastUpdated":1786097577000}'),i={name:"manual/errors.md"};function n(l,t,s,c,u,h){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="错误代码排错" tabindex="-1">错误代码排错 <a class="header-anchor" href="#错误代码排错" aria-label="Permalink to &quot;错误代码排错&quot;">​</a></h1><p>测连失败或聊天气泡报错时，点 <strong>查看详情</strong>，对照本页的<strong>错误代码</strong>（或文案关键词）。</p><p>详情一般包含：</p><ul><li><strong>错误代码</strong>（英文标识，如 <code>invalidApiKey</code>）</li><li><strong>错误原因</strong></li><li><strong>尝试修复</strong></li></ul><p>下列「代码」以 App 详情里展示的分类名为准（对应 i18n <code>llmTestError.*</code>）。</p><hr><h2 id="快速对照表" tabindex="-1">快速对照表 <a class="header-anchor" href="#快速对照表" aria-label="Permalink to &quot;快速对照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误代码</th><th>用户可见摘要</th><th>优先处理</th></tr></thead><tbody><tr><td><code>missingApiKey</code></td><td>请先填写 API 密钥</td><td>模型连接里填写密钥</td></tr><tr><td><code>invalidApiKey</code></td><td>密钥无效或过期</td><td>检查复制是否完整；控制台重新生成</td></tr><tr><td><code>forbidden</code></td><td>访问被拒绝</td><td>权限、模型是否开通</td></tr><tr><td><code>regionForbidden</code></td><td>地区不可用</td><td>换网络 / 代理 / 国际站</td></tr><tr><td><code>network</code></td><td>网络连接失败</td><td>网络、Base URL、防火墙</td></tr><tr><td><code>timeout</code></td><td>请求超时</td><td>网络；本地模型加大超时</td></tr><tr><td><code>modelNotFound</code></td><td>模型不存在</td><td>核对模型 ID</td></tr><tr><td><code>rateLimit</code></td><td>过于频繁</td><td>等待后重试</td></tr><tr><td><code>insufficientQuota</code></td><td>额度不足</td><td>充值 / 换密钥</td></tr><tr><td><code>spendingCapExceeded</code></td><td>月度消费上限</td><td>控制台提高 spend cap</td></tr><tr><td><code>contextLengthExceeded</code></td><td>上下文超限</td><td>降记忆；回复令牌设 None；换大上下文模型</td></tr><tr><td><code>anthropicMaxTokensRequired</code></td><td>Claude 缺 max_tokens</td><td>模型设置开启「回复令牌」</td></tr><tr><td><code>badRequest</code></td><td>参数有误</td><td>检查参数与兼容接口格式</td></tr><tr><td><code>serverError</code></td><td>服务端错误</td><td>稍后重试</td></tr><tr><td><code>requestFailed</code></td><td>请求失败</td><td>看详情原文</td></tr><tr><td><code>contentPolicy</code></td><td>安全审核未通过</td><td>重生成 / 换模型 / 改写</td></tr><tr><td><code>emptyContent</code></td><td>回复为空</td><td>重试；检查思考模型字段</td></tr><tr><td><code>modelAtCapacity</code></td><td>模型满载</td><td>等待或换模型</td></tr><tr><td><code>productNotActivated</code></td><td>产品未开通</td><td>控制台开通模型</td></tr><tr><td><code>visionUnsupported</code></td><td>不支持图片</td><td>换视觉模型或关附图</td></tr></tbody></table><hr><h2 id="分类详解" tabindex="-1">分类详解 <a class="header-anchor" href="#分类详解" aria-label="Permalink to &quot;分类详解&quot;">​</a></h2><h3 id="missingapikey" tabindex="-1">missingApiKey <a class="header-anchor" href="#missingapikey" aria-label="Permalink to &quot;missingApiKey&quot;">​</a></h3><ul><li><strong>现象</strong>：未填密钥无法请求。</li><li><strong>处理</strong>：设置 → 模型连接 → 填写 API 密钥。本地 Ollama 等可填占位字符（若校验非空）。</li></ul><h3 id="invalidapikey" tabindex="-1">invalidApiKey <a class="header-anchor" href="#invalidapikey" aria-label="Permalink to &quot;invalidApiKey&quot;">​</a></h3><ul><li><strong>现象</strong>：401 类、密钥无效。</li><li><strong>处理</strong>：无空格完整复制；确认国内/国际站与密钥匹配；重新生成密钥。</li></ul><h3 id="forbidden-regionforbidden" tabindex="-1">forbidden / regionForbidden <a class="header-anchor" href="#forbidden-regionforbidden" aria-label="Permalink to &quot;forbidden / regionForbidden&quot;">​</a></h3><ul><li><strong>现象</strong>：403、地区限制。</li><li><strong>处理</strong>：确认模型权限；换代理或国际站 Base URL。</li></ul><h3 id="network-timeout" tabindex="-1">network / timeout <a class="header-anchor" href="#network-timeout" aria-label="Permalink to &quot;network / timeout&quot;">​</a></h3><ul><li><strong>现象</strong>：连不上或长时间无响应。</li><li><strong>处理</strong>： <ul><li>检查 Base URL（本地勿用手机上的 <code>localhost</code>，用电脑局域网 IP）。</li><li>电脑防火墙放行端口；手机与电脑同一 Wi‑Fi。</li><li>弱网或本地慢模型：增大超时、换小模型。</li></ul></li></ul><h3 id="modelnotfound" tabindex="-1">modelNotFound <a class="header-anchor" href="#modelnotfound" aria-label="Permalink to &quot;modelNotFound&quot;">​</a></h3><ul><li><strong>现象</strong>：模型 ID 错误。</li><li><strong>处理</strong>：测连后从列表重选；本地与 <code>ollama list</code> / LM Studio 显示名一致。</li></ul><h3 id="ratelimit" tabindex="-1">rateLimit <a class="header-anchor" href="#ratelimit" aria-label="Permalink to &quot;rateLimit&quot;">​</a></h3><ul><li><strong>处理</strong>：降低发送频率；稍后重试；升级套餐。</li></ul><h3 id="insufficientquota-spendingcapexceeded" tabindex="-1">insufficientQuota / spendingCapExceeded <a class="header-anchor" href="#insufficientquota-spendingcapexceeded" aria-label="Permalink to &quot;insufficientQuota / spendingCapExceeded&quot;">​</a></h3><ul><li><strong>区别</strong>：额度用尽 vs <strong>项目月度消费上限</strong>（后者稍后重试通常无效）。</li><li><strong>处理</strong>：充值；或到控制台调整 spend cap（如 Google AI Studio Spend 页）。</li></ul><h3 id="contextlengthexceeded" tabindex="-1">contextLengthExceeded <a class="header-anchor" href="#contextlengthexceeded" aria-label="Permalink to &quot;contextLengthExceeded&quot;">​</a></h3><ul><li><strong>处理</strong>：设置 → 模型设置 → 减小记忆长度；将「回复令牌」设为 None（若适用）；换更大上下文模型。</li></ul><h3 id="anthropicmaxtokensrequired" tabindex="-1">anthropicMaxTokensRequired <a class="header-anchor" href="#anthropicmaxtokensrequired" aria-label="Permalink to &quot;anthropicMaxTokensRequired&quot;">​</a></h3><ul><li><strong>处理</strong>：Claude 必须带 max_tokens → 模型设置中开启「回复令牌」，不要设为 None。</li></ul><h3 id="badrequest" tabindex="-1">badRequest <a class="header-anchor" href="#badrequest" aria-label="Permalink to &quot;badRequest&quot;">​</a></h3><ul><li><strong>处理</strong>：检查 temperature 等参数；第三方兼容站是否真兼容 OpenAI/Anthropic 格式。</li></ul><h3 id="servererror-requestfailed-modelatcapacity" tabindex="-1">serverError / requestFailed / modelAtCapacity <a class="header-anchor" href="#servererror-requestfailed-modelatcapacity" aria-label="Permalink to &quot;serverError / requestFailed / modelAtCapacity&quot;">​</a></h3><ul><li><strong>处理</strong>：稍后重试；换端点或模型；持续失败联系服务商并附详情原文。</li></ul><h3 id="contentpolicy" tabindex="-1">contentPolicy <a class="header-anchor" href="#contentpolicy" aria-label="Permalink to &quot;contentPolicy&quot;">​</a></h3><ul><li><strong>处理</strong>：重生成、改写、换审核更松的模型；部分 NSFW 卡易触发输出拦截。</li></ul><h3 id="emptycontent" tabindex="-1">emptyContent <a class="header-anchor" href="#emptycontent" aria-label="Permalink to &quot;emptyContent&quot;">​</a></h3><ul><li><strong>处理</strong>：重试；部分思考模型只返回 reasoning → 看详情中的完整字段或换模型。</li></ul><h3 id="productnotactivated" tabindex="-1">productNotActivated <a class="header-anchor" href="#productnotactivated" aria-label="Permalink to &quot;productNotActivated&quot;">​</a></h3><ul><li><strong>处理</strong>：云厂商控制台开通对应产品/模型后再用当前密钥。</li></ul><h3 id="visionunsupported" tabindex="-1">visionUnsupported <a class="header-anchor" href="#visionunsupported" aria-label="Permalink to &quot;visionUnsupported&quot;">​</a></h3><ul><li><strong>处理</strong>：换支持视觉的模型；或不要发图 / 开启识图描写流程改用纯文本描写。</li></ul><hr><h2 id="服务层错误码-进阶" tabindex="-1">服务层错误码（进阶） <a class="header-anchor" href="#服务层错误码-进阶" aria-label="Permalink to &quot;服务层错误码（进阶）&quot;">​</a></h2><p>底层还可能出现 <code>LlmErrorCode</code>（日志 / 开发向）：</p><table tabindex="0"><thead><tr><th>代码</th><th>含义</th></tr></thead><tbody><tr><td><code>REQUEST_FAILED</code></td><td>非流式 HTTP 失败</td></tr><tr><td><code>STREAM_FAILED</code></td><td>流式失败</td></tr><tr><td><code>REQUEST_CANCELLED</code></td><td>用户取消</td></tr><tr><td><code>INVALID_CONFIG</code></td><td>配置无效</td></tr><tr><td><code>GET_MODELS_FAILED</code></td><td>拉模型列表失败</td></tr><tr><td><code>TEST_CONNECTION_FAILED</code></td><td>测连失败</td></tr><tr><td><code>PARSE_FAILED</code></td><td>响应解析失败</td></tr><tr><td><code>UNKNOWN</code></td><td>未分类</td></tr></tbody></table><p>用户侧请优先看详情里的分类名（上一节），不必强记本表。</p><hr><h2 id="本地模型专项" tabindex="-1">本地模型专项 <a class="header-anchor" href="#本地模型专项" aria-label="Permalink to &quot;本地模型专项&quot;">​</a></h2><p>连不上电脑上的 Ollama / LM Studio：见 <a href="/ultra_guides/troubleshoot">本地模型排错</a>。</p><p>App 测连 / 聊天报错（含错误代码）：见 <a href="/ultra_guides/manual/errors">使用手册 · 错误代码排错</a>。</p><div class="tip custom-block"><p class="custom-block-title">截图</p><p><img src="'+a+'" alt="错误详情"></p></div>',50)])])}const m=e(i,[["render",n]]);export{g as __pageData,m as default};
